        if response.status_code==200:
            print(json.dumps(dict(status=response.status_code,body=response.json(),cache=None)))
            break
    except httpx.HTTPError:
        pass
    time.sleep(1)
else:
    raise RuntimeError('New pod HTTP startup timed out')

